import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxCountryTaxes().listTaxCountryTaxes(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("country_taxes")) {
    Map<?, ?> countryTax = (Map<?, ?>) row;
    System.out.println(countryTax.get("id") + " " + countryTax.get("name") + " " + countryTax.get("tax_rate") + " "
            + countryTax.get("state_rules_count"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

