get_tax_country_tax.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxCountryTaxes().getTaxCountryTax(4);
Map<?, ?> countryTax = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("country_tax");
